/**
 * TASK: Complete the single actionPerformed method of this tally panel.
 *
 * The panel has buttons A and B and one shared listener (this class
 * implements ActionListener and both buttons register it). Every click
 * must update the tally label, which always looks like "a=<n> b=<m>".
 *
 * Example: fresh panel shows "a=0 b=0"; after clicking A twice and
 * B once it shows "a=2 b=1". Use e.getSource() to find out which
 * button fired the event.
 */
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class ClickTally extends JPanel implements ActionListener {

    private final JButton aButton = new JButton("A");
    private final JButton bButton = new JButton("B");
    private final JLabel tally = new JLabel("a=0 b=0");
    private int aClicks = 0;
    private int bClicks = 0;

    public ClickTally() {
        aButton.setName("a");
        bButton.setName("b");
        tally.setName("tally");
        add(aButton);
        add(bButton);
        add(tally);
        aButton.addActionListener(this);
        bButton.addActionListener(this);
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        // TODO: use e.getSource() to decide which counter to increment,
        // then update the tally label
    }
}

