public class ClickTallyTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            ClickTally panel = new ClickTally();
            java.awt.Component label = find(panel, "tally");
            java.awt.Component aC = find(panel, "a");
            java.awt.Component bC = find(panel, "b");
            check("tally starts at a=0 b=0", "a=0 b=0", textOf(label));
            if (aC instanceof javax.swing.JButton && bC instanceof javax.swing.JButton) {
                javax.swing.JButton a = (javax.swing.JButton) aC;
                javax.swing.JButton b = (javax.swing.JButton) bC;
                a.doClick();
                check("after one A click", "a=1 b=0", textOf(label));
                a.doClick();
                check("after two A clicks", "a=2 b=0", textOf(label));
                b.doClick();
                check("B counts separately", "a=2 b=1", textOf(label));
                b.doClick();
                b.doClick();
                check("after three B clicks", "a=2 b=3", textOf(label));
                a.doClick();
                check("A still counts after B clicks", "a=3 b=3", textOf(label));
            } else {
                failures++;
                System.out.println("FAIL  buttons not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

